WITH pk_list AS (
SELECT 'FACTALARMMELDINGEN' AS table_name, 'INCIDENT_NR' AS pk_column UNION ALL 
SELECT 'FACTBAANVAKBIJBEWEGING_PRE' AS table_name, 'BAANVAKNUMMER, DIMTREINNUMMER_TREINSERIEKEY, DIMDATUMKEY_VERKEER, DIMDIENSTREGELPUNTKEY_VAN, DIMDIENSTREGELPUNTKEY_NAAR' AS pk_column UNION ALL 
SELECT 'FACTBILJET' AS table_name, 'BILJET_NUMMER' AS pk_column UNION ALL 
SELECT 'FACTBTSINCIDENT' AS table_name, 'DIMDATUMKEY, DIMDEVICEKEY, DIMPOORTINCIDENTTYPEKEY, DIMPOORTKETENKEY, DIMTIJDKEY' AS pk_column UNION ALL 
SELECT 'FACTDRUKTETREIN' AS table_name, 'DIMTREINNUMMER_TREINSERIEKEY, DIMVERKEERSDATUMKEY, DIMTIJDKEY_VERTREK_UITVOER, DIMTIJDKEY_AANKOMST_UITVOER' AS pk_column UNION ALL 
SELECT 'FACTEVENEMENT' AS table_name, 'DIMEBVAITEMKEY' AS pk_column UNION ALL 
SELECT 'FACTINCIDENTASSISTENTIE' AS table_name, 'INCIDENTNR' AS pk_column UNION ALL 
SELECT 'FACTINCIDENTMKNS' AS table_name, 'INCIDENT_NR' AS pk_column UNION ALL 
SELECT 'FACTMCSSCAN' AS table_name, 'DRAGERKEY, DIMTREINNUMMER_TREINSERIEKEY, DIMDATUMKEY, DIMTIJDKEY' AS pk_column UNION ALL 
SELECT 'FACTMELDINGAPP' AS table_name, 'MELDING_ID' AS pk_column UNION ALL 
SELECT 'FACTMELDINGMKNS' AS table_name, 'INCIDENT_NR, MELDING_NR' AS pk_column UNION ALL 
SELECT 'FACTSECURITYSCAN' AS table_name, 'FSCANKEY' AS pk_column UNION ALL 
SELECT 'FACTSTATIONBELEVING' AS table_name, 'DIMDIENSTREGELPUNTKEY, DIMDATUMKEY, DIMSTATIONASPECTKEY' AS pk_column UNION ALL 
SELECT 'FACTSTATIONBELEVING_BEWERKT' AS table_name, 'DIMDIENSTREGELPUNTKEY, DIMDATUMKEY, DIMSTATIONASPECTKEY' AS pk_column UNION ALL 
SELECT 'FACTSTATIONSCAN' AS table_name, 'DIMDEVICEKEY, DIMDATUMKEY, DIMTIJDKEY' AS pk_column UNION ALL 
SELECT 'FACTVENSDIENST' AS table_name, 'DIMVENSDIENSTKEY' AS pk_column UNION ALL 
SELECT 'FACTVENSDIENSTACTIVITEIT' AS table_name, 'BRONACTIVITEIT_ID' AS pk_column UNION ALL 
SELECT 'FACTVENSMEDEWERKERINZET' AS table_name, 'DIMVENSDIENSTKEY, DIMMEDEWERKERKEY' AS pk_column 
)
SELECT 
  c.table_catalog
, c.table_schema
, c.table_name
, p.pk_column
, 'SELECT '''||c.table_name||''' AS table_name, '''||LISTAGG(c.column_name,',') WITHIN GROUP (ORDER BY c.column_name)||''' AS column_list, COUNT(1) AS aantal_records, HASH('||LISTAGG(c.column_name,',') WITHIN GROUP (ORDER BY c.column_name)
||') AS hashkey, COUNT(1) AS row_count FROM '||c.table_catalog||'.'||c.table_schema||'.'||c.table_name||' GROUP BY ALL HAVING COUNT(1) > 1 UNION ALL ' AS query_text
FROM information_schema.columns AS c
JOIN information_schema.tables  AS t ON c.table_catalog = t.table_catalog AND c.table_schema = t.table_schema AND c.table_name = t.table_name
JOIN pk_list                    AS p ON UPPER(p.table_name) = c.table_name
WHERE t.table_catalog = 'DIASSV'
AND t.table_type      = 'BASE TABLE'
AND t.table_schema    = 'SV_EDM'
AND t.table_name      LIKE 'FACT%'
GROUP BY ALL
ORDER BY table_name
;



