SELECT 'SELECT '''||table_name||''' AS table_name, CURRENT_DATE AS check_date, '||table_name||'KEY AS bk, COUNT(1) FROM '||table_schema||'.'||table_name||' GROUP BY ALL HAVING COUNT(1) > 1 UNION ALL ' AS check_query
FROM information_schema.tables
WHERE table_schema = 'SV_EDM'
AND table_name LIKE 'DIM%'
ORDER BY table_name
;


